pub fn dispatch_precondition(
    repo: &mut impl crate::kernel::Repository<Aggregate>, id: &str, args: PreconditionArgs, mutations: &mut Vec<crate::kernel::MutationRecord>, owner_deref: Vec<(&'static str, crate::kernel::DerefNode)>, command_deref: Vec<(&'static str, crate::kernel::DerefNode)>,
) -> crate::kernel::DispatchResult<Aggregate> {
        if let Some(v) = &args.description { v.check_invariants()?; }
        args.canonical.check_invariants()?;
    let with_references = crate::kernel::WithReferences { command_deref: &command_deref, args: &args, owner_deref: &owner_deref };
    let seed_projections = crate::kernel::seeded_projections(&with_references, AGGREGATE_PROJECTED_FIELDS);

    crate::kernel::dispatch(
        repo,
        crate::kernel::Hydrate::Act { id: id.to_string() },
        "Precondition",
        "Bluebook::Aggregate",
        "Aggregate",
        "bluebook, name.value",
        &with_references,
        &[
            crate::kernel::GivenSpec { description: "a rule says what it means", expr: Expr::Not(Box::new(Expr::Empty(Box::new(Expr::ToS(Box::new(Expr::Lookup("description.value"))))))), corrects_event: None },
            crate::kernel::GivenSpec { description: "a rule survives extraction", expr: Expr::Not(Box::new(Expr::Empty(Box::new(Expr::ToS(Box::new(Expr::Lookup("canonical.value"))))))), corrects_event: None },
        ],
        None,
        |record| {
        record.preconditions.push(Rule { description: args.description.clone().map(|v| v.value.clone()), canonical: args.canonical.value.clone() });
            Ok(())
        },
        &[

        ],
        &aggregate_invariants(),
        &["PreconditionAttached"],
        args.to_json(),
        mutations,
        seed_projections,
    )
}

